// graphNode.ts — the shapes the chains graph is made of, as the Rust build writes them (generated by ts-rs, see k7-wasm/docs/chains.md).
// A reader would get wrong that `RawNode` and `GraphNode` are one struct: the layout adds the position, and drops the rank it was told.

import type {
  RawEdge as BuiltEdge,
  RawNode as BuiltNode,
  EdgeAutomation,
  EdgeInsert,
  Jack,
  Kind,
  Laid,
  Pt,
} from "@studio/k7-wasm/types";

export type { EdgeAutomation, EdgeInsert, Jack, Kind, Pt };

/** A node as the build leaves it: no position yet, a rank for the layout. */
export type RawNode = Omit<BuiltNode, "x" | "y"> & { x?: number; y?: number };

/** A node as the renderer receives it: the build's fields plus its place. */
export type GraphNode = Omit<BuiltNode, "x" | "y" | "rank"> & {
  x: number;
  y: number;
  rank?: number;
};

/** A cable as the build leaves it: its two ends, and the weight the layout keeps them tight by. */
export type RawEdge = Omit<BuiltEdge, "points" | "side" | "glued">;

/** A cable laid out: the polyline the layout routed, the lane it skips by and whether its cards touch. */
export type GraphEdge = Omit<BuiltEdge, "points" | "weight"> & { points: Pt[] };

export interface LaidOutGraph extends Omit<Laid, "nodes" | "edges"> {
  nodes: GraphNode[];
  edges: GraphEdge[];
}

// A track's live mixer state (volume in dB, pan 0..1, flags 0/1), on its own channel.
export interface TrackControlValues {
  volume: number;
  pan: number;
  mute: number;
  solo: number;
  arm: number;
  /** Heard 10 dB up from the mixer's highlight button — apps/k7-daw-frontend/packages/song/docs/highlight.md. */
  highlight?: number;
}
